\label{def:tree}
    Let $\mathcal{T}$ be a rooted tree structure on the vertex set $[L]$, namely a connected, acyclic graph with a designated root $o\in [L]$.  
    For each $i\in [L]\setminus \{o\}$, denote $\operatorname{pa}(i)$ as its unique parent, which represents the edge $(i,\operatorname{pa}(i))$. 
    Then the tree structure $\mathcal{T}$ can be specified as
    \begin{align}
        \mathcal{T} := \big\{ \{o\}, \big(i,\operatorname{pa}(i)\big)_{i\in [L] \setminus \{o\}}\big\}. \label{eq:tree structure.}
    \end{align}
    In particular, repeatedly following the parent map from any nonroot vertex reaches $o$ after finite steps.
    We further denote $\mathfrak{T}$ as the set of all trees on $[L]$ and suppress its dependence on $L$.


    For any discrete random vector $Z = (Z_1,\cdots,Z_L)$, we say that $Z$ follows a tree distribution if there exists a dependence tree $\mathcal{T} \in \mathfrak{T}$ such that the law of $Z$ admits the following factorization
    \begin{align}
        p_Z(z_1,\cdots,z_L) = p_o(z_o) \prod_{i\neq o} p_i(z_i \mid z_{\operatorname{pa}(i)}). \label{eq:follow dependence tree}
    \end{align}
    Here the root $o$ and parent map $\operatorname{pa}(i)$ correspond to tree structure $\mathcal{T}$. 
    We further say that $p_Z$ factorizes according to $\mathcal{T}$.

\label{def:tree-mixtures}

Let $\mathcal{T}$ be a rooted tree on the index set $[L]$, with root $o \in [L]$ and parent map $\operatorname{pa}(\cdot)$ for nonroot vertices as in Definition \ref{def:tree}.
A $J$-state \emph{hidden Markov tree} on $\mathcal{T}$ is a distribution $q$ on $\mathbb V^L$ of the form
\begin{align}
    q(x) = \sum_{z\in[J]^L} q(x,z) \qquad \text{with}\qquad  q(x,z) := \nu(z_o) \prod_{i\neq o} A_i\big(z_i, z_{\operatorname{pa}(i)}\big) \prod_{i=1}^L B_i(x_i, z_i). \label{eq:hidden-tree-law}
\end{align}
Here, $\nu$ is the root-state distribution on $[J]$. For hidden state $b\in[J]$, the transition kernel $A_i(\cdot,b)$ is a distribution on $[J]$ for $i\neq o$, and the emission kernel $B_i(\cdot,b)$ is a distribution on $\mathbb V$ for $i\in[L]$.


The class $\mathcal{M}_{J,R}$ consists of all mixtures of $R$ such models:
\[
    q(x)=\sum_{r=1}^R \pi_r q_r(x)
    \qquad \text{with} \qquad \pi_r\geq0,\quad \sum_{r=1}^R\pi_r=1,
\]
where each $q_r$ is a $J$-state hidden Markov tree with its own topology $\mathcal{T}_r$, root distribution, transition kernels, and emission kernels.

\label{def:projection error}
    Let $\mathcal{F}$ be a class of probability distributions on $\mathbb V^L$. 

    For any distribution $p$ on $\mathbb V^L$, define the KL approximation error w.r.t.~$\mathcal{F}$ by 
    \begin{align}\label{eq:projection error}
        \mathsf{Proj}_{\mathcal{F}}(p) := \inf_{q\in \mathcal{F}} D_{\mathrm{KL}}\big(p\|q\big). 
    \end{align}
    In particular, we write $\mathsf{Proj}_{J,R} := \mathsf{Proj}_{\mathcal{M}_{J,R}}$ for the MHMT class $\mathcal{M}_{J,R}$.

\label{thm:tree-mixture-estimation}

There exists a transformer class $\Theta$ of the form \eqref{eq:transformer predictor}, with an architecture depending only on $(n,L,V,J,R)$ (specified in Proposition \ref{prop:appendix-parallel-mixture} with $\delta=\varepsilon=1/n$), such that for any distribution $p^\star$ on $\mathbb V^L$, the ERM $\widehat{\theta}$ over $\Theta$ computed from $n$ i.i.d.~samples drawn from $p^\star$ satisfies
\begin{align}
    \mathbb E[\mathcal{L}(\widehat{\theta})] \leq C_{1} \bigg(\frac{s_{\mathsf{max}}}{L} \mathsf{Proj}_{J,R}(p^\star) + \frac{K_{\rm par}}{n}\, \mathsf{poly}\log(n,L,V,J,R) \bigg).  \label{eq:estimation error}
\end{align}

Here, $C_{1}>0$ is a universal constant, the expectation is over training samples, and 
\begin{align}\label{eq:Kpar}
K_{\rm par} := R[LJ(J+V)+J^3].
\end{align}

\label{thm:end-to-end}
Assume the conditions and adopt the notation of Theorem \ref{thm:tree-mixture-estimation}.

Let $p_{Y\mid S}$ denote the output distribution of the $T$-step MDM sampler using the ERM-based mask predictor $p_{\widehat{\theta}}$ and the realized unmasking sets $\mathcal{S}=(S^1,\ldots,S^T)$ with $|S^t| = s_t$.



Then for any $1\leq T \leq L$, one has 
\begin{align}
    & \mathbb E_{\{X^{(i)}\}_{i=1}^n,S} \big[D_{\mathrm{KL}} \big( p^\star \,\|\, p_{Y\mid S}\big)\big] \notag \\
    &\quad \leq C_{2}\bigg( \varepsilon_{\mathsf{parall}}(p^\star;s) + s_{\mathsf{max}} \mathsf{Proj}_{J,R}(p^\star) + \frac{L K_{\rm par}}{n}\, \mathsf{poly}\log (n,L,V,J,R)\bigg), \label{eq:sampling error}
\end{align}
where $C_{2}>0$ is a universal constant, and the expectation is over the training samples and random unmasking sets $S$.

\label{rem:parallel}

Recent sampling analyses \citep{li2026breaking,wainwright2026data} characterize the parallelization error $\varepsilon_{\mathsf{parall}}(p^\star;s)$ in terms of the information-theoretic structure of the data distribution $p^\star$ and the unmasking schedule $s$.

For instance, as shown in \citet{chen2025optimal}, for any $T=\Omega(\log L)$, there exists a schedule $s^{\mathsf{DTC}}$ depending only on $(L,T)$\footnote{The original construction in \citet{chen2025optimal} requires an estimate of DTC. A straightforward modification yields a schedule that depends only on $(L,T)$ with the same guarantees. For completeness, we present the construction $s^{\mathsf{DTC}}$ in Appendix \ref{app:TC and DTC parallel error}.} such that
    \begin{align}



        \varepsilon_{\mathsf{parall}}(p^\star;s^{\mathsf{DTC}})
        \le \frac{6\log(eL)}{T}\,\mathsf{DTC}(p^\star). \label{eq:TC and DTC control for parallelization error}
    \end{align}
    Here 

    \textit{dual total correlation} (DTC) is defined as
    \begin{align*}
        \mathsf{DTC}(p^\star):= H(X) - \sum_{i=1}^L H(X_i\mid X_{[L]\setminus \{i\}}),
    \end{align*}
    where $X\sim p^\star$ and $H$ denotes the entropy. 



    In particular, DTC can be substantially smaller than the sequence length $L$ for structured data distributions, 

    e.g., an MHMT with star-shaped components satisfies $\mathsf{DTC}(p^\star) \leq \log(RJ)$.
    We refer to \citet{chen2025optimal}, \citet{dmitriev2026efficient} and \citet{zhao2026adaptation} for further discussion of distributions with small $\mathsf{TC}$ and $\mathsf{DTC}$.

\label{prop:gen error}
        Assume $n,V\ge 3$. 
        Let $\Theta = \Theta (D,N,M,D_{\mathrm{ff}},B,S;R_{\mathrm{embed}},G)$ be the parameter class in Section~\ref{sec:estimator} with $D,N,M,D_{\mathrm{ff}} \ge 1$, and $B,R_{\mathrm{embed}},G>0$.
        Define 
        \begin{align*}
            P_{\mathrm{tr}} :=(V+1)D+LD+N(3MD^2+2DD_{\mathrm{ff}})+DV = O(DV+LD+NMD^2+NDD_{\mathrm{ff}}),
        \end{align*}
        as the number of parameters in this function class and suppose the sparsity $1\le S\le P_{\mathrm{tr}}$ is an integer.
        There exists a constant $A_{\mathrm{TF}}\geq e$, depending only on $N$, $M$, $B$, $R_{\mathrm{embed}}$, satisfying
        \[
        \log A_{\mathrm{TF}}
        \leq CN^2\log\big(eNM(B\vee1)(R_{\mathrm{embed}}\vee1)\big),
        \]
        such that
        \begin{align}
            \mathbb E[\mathcal{L}(\widehat{\theta})] \lesssim \varepsilon_{\mathsf{approx}}(\Theta) + (G+\log V) \cdot \frac{C(\Theta)\log (en) + 1 }{n}.
        \end{align}
        Here the capacity of $\Theta$ satisfies
        \begin{align*}
            C(\Theta):=S\bigg[\log\frac{eP_{\mathrm{tr}}}{S}
            +\log A_{\mathrm{TF}}\bigg],
        \end{align*}
        $\widehat{\theta}$ is the ERM estimator in \eqref{eq:ERM estimator} and the expectation is taken over training data $\{X^{(j)}\}_{j=1}^n$.

\label{prop:tree-mixture-approximation}
    Fix integers $L,V\geq2$, $J,R\geq1$,
    $0<\delta,\varepsilon\leq1/2$,  and a masking schedule $s=(s_1,\cdots,s_T)$ with $s_{\max}:= \max_{t\in [T]} s_t$, as in Section \ref{sec:prelim}. 
    There exists a sparse transformer class $\Theta$, with architectural budgets
    depending only on $(L,V,J,R,\delta,\varepsilon)$, such that
    \begin{align}
        \varepsilon_{\mathsf{approx}}(\Theta)
        \leq
        \frac{s_{\max}}{L}\mathsf{Proj}_{J,R}(p^\star)
        +s_{\max}\log\frac{1}{1-\delta}
        +2\varepsilon
        \label{eq:tree-mixture-approximation}
    \end{align}
    for every distribution $p^\star$ on $\mathbb V^L$.

\label{lem:continuous latent representation}
      Suppose that there exists a probability distribution $\mu$ on $[0,1]^k$ such that, 
      \begin{align}
            p^{\star}(x) = \int_{[0,1]^k} \prod_{i=1}^L p_i(x_i \mid z) \mu(\mathrm{d} z), \quad \forall \, x\in \mathbb V^L  \label{eq:continuous latent repre}
      \end{align}
      We further assume that for some $A\ge 0$ and $\alpha\in (0,1]$, the kernel admits the following continuity condition:
      \begin{align}
            D_{\mathrm{KL}}\big(p_i(\cdot \mid z) \,\|\, p_i(\cdot \mid z')\big) \leq A^2 \|z-z'\|_2^{2\alpha}, \quad \forall i \in [L],\quad \forall z,z' \in [0,1]^k.  \label{eq:continuour latent repre KL condition}
      \end{align}

      Then for any integers $J,R\geq 1$, it holds that, 
      \begin{align}
            \mathsf{Proj}_{J,R}(p^\star)\leq \mathsf{Proj}_{1,R}(p^\star) \leq C_{k,\alpha} L A^2 R^{-2\alpha/k} \label{eq:cont latent repre proj error}.
      \end{align}
      Here constant $C_{k,\alpha}$ depends only on $k,\alpha$. In particular, condition \eqref{eq:continuour latent repre KL condition} holds if
      $p_i(\cdot \mid z)=\mathrm{softmax}(g_i(z))$ with logits
            $g_i:[0,1]^k \to \mathbb R^V$ satisfying
      \begin{align}
      \|g_i(z)-g_i(z')\|_2 \leq \sqrt{2} A\|z-z'\|_2^\alpha, \quad \forall i\in [L], \quad z,z' \in [0,1]^k \label{eq:continuous latent repre sufficient for KL}
      \end{align}

\label{lem:renyi-compression}
Let $p^\star$ be a distribution on $\mathbb V^L$ and $\alpha\in(0,1)$. For any integers $J\geq1$ and $R\geq2$, it holds that
\begin{align}
    \mathsf{Proj}_{J,R}(p^\star)\leq\mathsf{Proj}_{1,R}(p^\star)
    \leq L\log V\min\bigg\{1,
    \bigg(\frac{e^{H_\alpha(p^\star)}}{R}\bigg)^{(1-\alpha)/\alpha}\bigg\}.
    \label{eq:renyi-error-bound}
\end{align}

\label{lem:kl}
Recall the definition of $\tau$, $M^{\tau}$ and $W^{\tau}$ in Section~\ref{sec:mdm}.
Conditioned on $(\tau,M^{\tau})$, draw $I$ uniformly from $M^\tau$.

Then the excess risk $\mathcal{L}(\theta)$ satisfies
\begin{align}
 \mathcal L(\theta)&:=\overline{ R}(p_{\theta})-\overline{ R}(p^\star)\notag\\
 &=\mathbb E_{\tau,M^\tau,I,\,X\sim p^\star}
   \Big[D_{\mathrm{KL}} \big(p_I^\star(\cdot\mid X_{W^\tau})\, \|\,
                        p_{\theta,I}(\cdot\mid X_{W^\tau})\big)\Big].
 \label{eq:kl-risk}
\end{align}
Here $\overline{R}(p_{\theta}):= \mathbb E_{X\sim p^\star}[\ell_{p_{\theta}}(X)]$ is the risk of the conditional predictor $p_{\theta}$.

Subtract the cross-entropy of the true conditional predictor from that of the network and introduce a conditionally uniform $I \sim \mathrm{Unif}(M^\tau)$. Then
\begin{align*}
 \overline{R}(p_{\theta})-\overline{R}(p^\star)
&=\mathbb E_{\tau,M^{\tau},X\sim p^\star}\Big[\frac1{|M^\tau|}\sum_{i\in M^\tau}
       \log\frac{p_i^\star(X_i\mid X_{W^\tau})}{p_{\theta,i}(X_i\mid X_{W^\tau})}\Big]\\
       &=\mathbb E_{\tau,M^{\tau},I,X\sim p^\star}\Big[\log\frac{p_I^\star(X_I\mid X_{W^\tau})}
                          {p_{\theta,I}(X_I\mid X_{W^\tau})}\Big].
\end{align*}
Conditioned on $(\tau,M^{\tau},X_{W^\tau},I)$, the token distribution $X_I$ follows the law $p_I^\star(\cdot\mid X_{W^\tau})$. 
Taking the conditional expectation therefore gives the KL divergence in \eqref{eq:kl-risk}.

\label{def:regularization}
    For $0<\delta<1$, define the regularization kernel $Q_\delta(a,b):=(1-\delta)\mathbf1\{a=b\}+\delta/V$.
    For any distribution $q$ on $\mathbb V^L$, define its $\delta$-regularization by
      \begin{align}
      q^\delta(y):=(P_\delta q)(y)
      :=\sum_{x\in\mathbb V^L}q(x)\prod_{i=1}^LQ_\delta(x_i,y_i),
      \qquad y\in\mathbb V^L.
    \label{eq:refresh}
      \end{align}
      This transition independently replaces each token by a uniform token with probability $\delta$.

\label{lem:regularization}
Let $0<\delta<1$, $\rho_\delta:=\delta/V$, and $G_\delta:=\log(V/\delta)$. The following properties hold.
\begin{enumerate}[label=\textup{(\roman*)}]
    \item If $q=\sum_{r=1}^R\pi_rq_r\in\mathcal M_{J,R}$, then
    \begin{align}
        q^\delta=\sum_{r=1}^R\pi_rq_r^\delta\in\mathcal M_{J,R},
        \quad
        B_{i,r}^\delta(v,z)
        =(1-\delta)B_{i,r}(v,z)+\frac{\delta}{V}.
        \label{eq:refresh-mixture}
    \end{align}
    Here $q_r^\delta=P_\delta q_r$ is obtained by replacing the emission tables $B_{i,r}$ with $B_{i,r}^\delta$ as in \eqref{eq:hidden-tree-law}. 
    The root distributions, transitions, component trees, and mixture weights are unchanged.

    \item For any distribution $q$ on $\mathbb V^L$, any $y\in\mathbb V^L$, and any masked sequence $c\in\overline{\mathbb V}^L$,
    it holds that:
    \begin{align}
        q^\delta(y) \geq\rho_\delta^L,\quad  q^\delta(y)\geq(1-\delta)^Lq(y),\quad q_i^\delta(v\mid c)\geq\rho_\delta, \quad \forall i\notin W(c),\text{ and } v\in\mathbb V.
        \label{eq:refresh-positive}
    \end{align}
    Here $W(c):=\{j\in[L]:c_j\ne\mathtt M\}$ and
    $q_i^\delta(v\mid c):=\mathbb P_{X\sim q^\delta}[X_i=v\mid X_{W(c)}=c_{W(c)}]$.
    Hence, $-G_{\delta}\le \log q_i^{\delta}(v\mid c) \le 0$. 

    \item For any distributions $p,q$ on $\mathbb V^L$,
    \begin{align}
        D_{\mathrm{KL}}(p\|q^\delta)
        \leqD_{\mathrm{KL}}(p\|q)+L\log\frac1{1-\delta}.
        \label{eq:refresh-kl}
    \end{align}
\end{enumerate}

\label{lem:decomp}
Fix $0<\delta<1$ and a fixed-cardinality masking schedule $s=(s_1,\ldots,s_T)$, with $s_t\in\mathbb N_+$ and $\sum_{t=1}^T s_t=L$. For any distribution $q$ on $\mathbb V^L$,
\begin{align}
    \varepsilon_{\mathsf{approx}}(\Theta)
    \leq\frac{s_{\max}}{L}D_{\mathrm{KL}}(p^\star\|q^\delta)
       +2d_{\infty,\mathrm{mask}}(F^{\delta,q},\mathcal F(\Theta)),
    \label{eq:dist-net}
\end{align}
where $s_{\max}:=\max_t s_t$ and $\varepsilon_{\mathsf{approx}}(\Theta):=\inf_{\theta\in\Theta}\mathcal L(\theta)$. 
In particular, if function class $\mathcal F(\Theta)$ satisfies
\[
    \sup_{q\in\mathcal M_{J,R}}
    d_{\infty,\mathrm{mask}}(F^{\delta,q},\mathcal F(\Theta))
    \leq\epsilon,
\]
then
\begin{align}
    \varepsilon_{\mathsf{approx}}(\Theta)
    \leq\frac{s_{\max}}{L}\mathsf{Proj}_{J,R}(p^\star)
       +s_{\max}\log\frac1{1-\delta}+2\epsilon.
    \label{eq:approx-oracle}
\end{align}
The same conclusion holds for any nonempty subclass $\mathcal Q\subseteq\mathcal M_{J,R}$, with the uniform approximation condition imposed on $\mathcal Q$ and $\mathsf{Proj}_{J,R}$ replaced by $\mathsf{Proj}_{\mathcal Q}(p^\star) := \inf_{q\in \mathcal{Q}} D_{\mathrm{KL}}(p^\star \| q)$.

Fix $q$ and write $r=q^\delta$. Let $r_{\mathrm{cond}}$ denote its conditional predictor on masked positions. 
We use the same training experiment as in Section~\ref{sec:prelim}: $\mathbb P[\tau=t]=s_t/L$, $M^\tau$ is uniform among subsets of size $m_\tau:=\sum_{u=1}^\tau s_u$, and $I$ is uniform in $M^\tau$. 
Write $W^\tau=[L]\setminus M^\tau$, and let $X\sim p^\star$. 
As in Section \ref{sec:prelim}, $X_{W^\tau}$ denotes the sequence obtained by replacing all tokens outside $W^\tau$ with $\mathtt M$.
Define

\[
    \mathcal L(r_{\mathrm{cond}})
    :=\mathbb E\big[D_{\mathrm{KL}}\big(p_I^\star(\cdot\mid X_{W^\tau})
         \,\|\,r_I(\cdot\mid X_{W^\tau})\big)\big].
\]

By Lemma~\ref{lem:kl}, adding and subtracting the log conditional probability under $r$ gives
\begin{align}
    \mathcal L(\theta)
    &=\mathbb E\bigg[\log\frac{p_I^\star(X_I\mid X_{W^\tau})}
                                 {p_{\theta,I}(X_I\mid X_{W^\tau})}\bigg]\notag\\
    &=\mathcal L(r_{\mathrm{cond}})
      +\mathbb E\bigg[\log\frac{r_I(X_I\mid X_{W^\tau})}
                              {p_{\theta,I}(X_I\mid X_{W^\tau})}\bigg].
    \label{eq:proof-exact-mixture-network-split}
\end{align}
For any $f,g\in\mathbb R^V$, the log-sum-exp function is one-Lipschitz in the maximum norm. Hence,
\begin{align}
    |\log\mathrm{softmax}_v(f)-\log\mathrm{softmax}_v(g)|
    &\leq |f_v-g_v|
       +\bigg|\log\sum_{a=1}^V e^{f_a}
              -\log\sum_{a=1}^V e^{g_a}\bigg|\notag\\
    &\leq2\|f-g\|_\infty.
    \label{eq:proof-logsoftmax-lipschitz}
\end{align}
Since $r_i(\cdot\mid x)=\mathrm{softmax}(F_{i,\cdot}^{\delta,q}(x))$ for $i\notin W(x)$, applying this bound in \eqref{eq:proof-exact-mixture-network-split} and taking the infimum over $\theta\in\Theta$ yields
\[
    \varepsilon_{\mathsf{approx}}(\Theta)
    \leq\mathcal L(r_{\mathrm{cond}})
       +2d_{\infty,\mathrm{mask}}(F^{\delta,q},\mathcal F(\Theta)).
\]

It remains to control $\mathcal L(r_{\mathrm{cond}})$ by $D_{\mathrm{KL}}(p^\star\|r)$. We use a subset-averaging argument, analogous to the entropy calculation in \citet[proof of Theorem~3.3]{chen2025optimal}. For $W\subseteq[L]$, denote by $p_W^\star$ and $r_W$ the corresponding marginals. Let
\[
    \overline d_j
    :=\binom Lj^{-1}\sum_{\substack{W\subseteq[L]\\|W|=j}}
       D_{\mathrm{KL}}(p_W^\star\|r_W),\quad \forall \, 0\leq j\leq L,
\]
and write $\Delta_j:=\overline d_{j+1}-\overline d_j$ for $0\leq j<L$. By the KL chain rule, for $i\notin W$,
\begin{align*}
    D_{\mathrm{KL}}(p_{W\cup\{i\}}^\star\|r_{W\cup\{i\}})
    -D_{\mathrm{KL}}(p_W^\star\|r_W)
    =\mathbb E_{X_W\sim p_W^\star}
      \big[D_{\mathrm{KL}}\big(p_i^\star(\cdot\mid X_W)
           \,\|\,r_i(\cdot\mid X_W)\big)\big].
\end{align*}
If $W$ is a uniform $j$-subset and $I$ is uniform in $[L]\setminus W$, then $W\cup\{I\}$ is a uniform $(j+1)$-subset. Averaging the preceding identity gives
\begin{align}
    \mathbb E_{W,I,X_W}\big[
        D_{\mathrm{KL}}\big(p_I^\star(\cdot\mid X_W)
           \,\|\,r_I(\cdot\mid X_W)\big)\big]
    =\Delta_j\geq0.
    \label{eq:proof-kl-level-increment}
\end{align}
All these divergences are finite because $r$ has full support. Since $\overline d_0=0$ and $\overline d_L=D_{\mathrm{KL}}(p^\star\|r)$,
\begin{align}
    \sum_{j=0}^{L-1}\Delta_j=D_{\mathrm{KL}}(p^\star\|r).
    \label{eq:proof-kl-increments-telescope}
\end{align}
At training time $t$, the context set $W^t$ is uniform of size $L-m_t$, where $m_t=\sum_{u=1}^t s_u$. 
Therefore,
\begin{align}
    \mathcal L(r_{\mathrm{cond}})
    =\frac1L\sum_{t=1}^T s_t\Delta_{L-m_t}
    \leq\frac{s_{\max}}{L}\sum_{j=0}^{L-1}\Delta_j
     =\frac{s_{\max}}{L}D_{\mathrm{KL}}(p^\star\|r).
    \label{eq:proof-general-schedule-kl}
\end{align}
Here we use $\Delta_j\geq0$ and the fact that the indices $L-m_t$ are distinct, since $s_t\geq1$. Combining this with the network approximation bound proves \eqref{eq:dist-net}.

Under the uniform approximation condition, Lemma~\ref{lem:regularization}(iii) further gives, for every $q\in\mathcal M_{J,R}$,
\begin{align*}
    \varepsilon_{\mathsf{approx}}(\Theta)
    &\leq\frac{s_{\max}}{L}D_{\mathrm{KL}}(p^\star\|q^\delta)+2\epsilon\\
    &\leq\frac{s_{\max}}{L}D_{\mathrm{KL}}(p^\star\|q)
       +s_{\max}\log\frac1{1-\delta}+2\epsilon.
\end{align*}
Taking the infimum over $q\in\mathcal M_{J,R}$ proves \eqref{eq:approx-oracle}. The same argument applies when this infimum is restricted to $\mathcal Q$.

Lemma \ref{lem:decomp} reduces Proposition \ref{prop:tree-mixture-approximation} to uniformly approximating the regularized conditional logits $F^{\delta,q}$ over $q \in \mathcal{M}_{J,R}$ using a transformer class.
We establish this approximation first for a single tree in Appendix \ref{app:single-tree-parallel} and then for mixtures in Appendix \ref{app:mixture-parallel-construction}.

\label{lem:single-tree-parallel}
Let $q$ be a $J$-state hidden Markov tree model on $[L]$, with root $o$, root distribution $\nu$, transition tables $A_i$, and emission tables $B_i$ satisfying $B_i(v,z)\ge\rho_\delta$. There exists a parameter class
$\Theta=\Theta(D,N,M,D_{\rm ff},B,S;\sqrt3,G_\delta)$ with budgets depending only on $(L,V,J,\delta,\varepsilon)$, and a parameter $\theta \in \Theta$ satisfying
\begin{align}
 \sup_{c:\,W(c)\ne[L]}\max_{i\notin W(c),\,v\in\mathbb V}
 |F_{\theta,i,v}(c)-\log q_i(v\mid c)|\le\varepsilon.
 \label{eq:single-tree-parallel-goal}
\end{align}
The architectural budgets can be chosen as
\begin{align}
 N&\le Cb_*^3,\qquad M\le2,\qquad \log B\le Cb_*^2,\notag\\
 D&\le C\big[L+V+(J^3+JV)b_*^3\big],\qquad
 D_{\rm ff}\le C\big[LV+(J^3+JV)b_*^3\big],\notag\\
 S&\le C\big[L(J^2+JV)+J^3+JV\big]b_*^{10}.
 \label{eq:single-tree-parallel-budgets}
\end{align}
Before the output embedding, the construction also contains a coordinate $\widehat h_i(c)$ at every row satisfying
\begin{align}
 \sup_{c\in\overline{\mathbb V}^L}\max_{i\in[L]}
 |\widehat h_i(c)-\log q(c)|\le\varepsilon,
 \label{eq:single-tree-evidence-goal}
\end{align}
which approximates the log context likelihood $\log q(c)$. 
The budgets are independent of the topology and probability tables.

\label{prop:appendix-parallel-mixture}
Fix $R\ge1$ and set
\[
 H_R:=(L+1)G_\delta+\log(64LJR/\varepsilon),\qquad
 b_R:=\log(eLJVRH_R/\varepsilon),
\]
where $G_{\delta} := \log (V/\delta)$.
There exists one parameter class $\Theta=\Theta(D,N,M,D_{\rm ff},B,S;R_{\mathrm{embed}},G_\delta)$ with $R_{\mathrm{embed}} = \sqrt{3}$ 
such that
\begin{align}
 \sup_{q\in\mathcal M_{J,R}}
 d_{\infty,\mathrm{mask}}(F^{\delta,q},\mathcal F(\Theta))\le\varepsilon,
 \label{eq:appendix-tree-uniform-realization}
\end{align}
with
\begin{align}
 N&\le Cb_R^3,\qquad M\le2R,\qquad \log B\le Cb_R^2,\notag\\
 D&\le C\big[L+V+R(J^3+JV)b_R^3\big],\qquad
 D_{\rm ff}\le C\big[LV+R(J^3+JV)b_R^3\big],\notag\\
 S&\le CR\big[L(J^2+JV)+J^3+JV\big]b_R^{10}.
 \label{eq:appendix-tree-parallel-budgets}
\end{align}
For mixtures sharing a common rooted topology, two heads suffice. The same bounds hold when the component topologies are restricted to any prescribed family of rooted trees on $[L]$.

\label{lem:conditional-mixture}
  Fix $c\in\overline{\mathbb V}^L$ and write $W=W(c)$. Let $q$ be a single hidden Markov tree model with root $o$, root distribution $\nu$, transitions $A_i$, and emissions $B_i$. 
  For each vertex $i$, let $\mathcal V_i$ be the subtree rooted at $i$, including $i$, and write $\mathcal{V}_i^c:= [L]\setminus \mathcal{V}_i$. For $S\subseteq[L]$, write $c_S$ for the event $\{X_{W\cap S}=c_{W\cap S}\}$, and define
\[
 g_i(z,c):=\begin{cases}B_i(c_i,z),&i\in W,\\1,&i\notin W.\end{cases}
\]
Define the upward messages by
\begin{align}
 \alpha_i(z,c)&:=g_i(z,c)\prod_{u\in\operatorname{ch}(i)}m_u(z,c),\qquad i\in[L],\notag\\
 m_i(a,c)&:=\sum_{z=1}^J A_i(z,a)\alpha_i(z,c),\qquad i\ne o,
 \label{eq:message-identities-upward}
\end{align}
and the downward messages by $\beta_o(z,c):=\nu(z)$ and
\begin{align}
 \beta_i(z,c)
 :=\sum_{a=1}^J A_i(z,a)\beta_{\operatorname{pa}(i)}(a,c)g_{\operatorname{pa}(i)}(a,c)
      \prod_{u\in\operatorname{ch}(\operatorname{pa}(i))\setminus\{i\}}m_u(a,c),\qquad i\ne o.
 \label{eq:message-identities-downward}
\end{align}
Here empty products equal one. These messages satisfy
\begin{align}
 \alpha_i(z,c)\beta_i(z,c)
 &=\mathbb P_q[Z_i=z,c],\qquad
 q(c)=\sum_{z=1}^J\alpha_i(z,c)\beta_i(z,c).
 \label{eq:message-identities-joint}
\end{align}
Consequently, whenever $q(c)>0$, for every $i\notin W$ and $v\in\mathbb V$,
\begin{align}
 q_i(v\mid c)
 =\frac{\sum_{z=1}^J\alpha_i(z,c)\beta_i(z,c)B_i(v,z)}
        {\sum_{z=1}^J\alpha_i(z,c)\beta_i(z,c)}.
 \label{eq:message-identities-conditional}
\end{align}
For a mixture $q=\sum_{r=1}^R\pi_rq_r\in\mathcal M_{J,R}$, compute the messages on each component tree. Then, whenever $q(c)>0$, for every $i\notin W$ and $v\in\mathbb V$,
\begin{align}
 q_i(v\mid c)
 =\frac{\sum_{r=1}^R\pi_r\sum_{z=1}^J
          \alpha_{i,r}(z,c)\beta_{i,r}(z,c)B_{i,r}(v,z)}
        {\sum_{r=1}^R\pi_r\sum_{z=1}^J
          \alpha_{i,r}(z,c)\beta_{i,r}(z,c)}.
 \label{eq:message-identities-mixture}
\end{align}

\label{lem:single-tree-message}
Under the assumptions of Lemma~\ref{lem:single-tree-parallel}, suppose the rooted tree has height $h$.
There exists a parameter class
$\Theta=\Theta(D,N,M,D_{\rm ff},B,S;\sqrt3,G_\delta)$ and a parameter $\theta\in \Theta$ satisfying

\begin{align}
 \sup_{c:\,W(c)\ne[L]}\max_{i\notin W(c),\,v\in\mathbb V}
 |F_{\theta,i,v}(c)-\log q_i(v\mid c)|\le\varepsilon,
 \label{eq:single-tree-goal}
\end{align}
with
\begin{align}
 N&\le C(h+1)b_*^2,\qquad M\le1,\qquad\log B\le Cb_*^2,\notag\\
 D&\le C\big[L+V+(J^2+JV)b_*^3\big],\qquad
 D_{\rm ff}\le C\big[LV+(J^2+JV)b_*^3\big],\notag\\
 S&\le CL(J^2+JV)b_*^8.
 \label{eq:single-tree-message-budgets}
\end{align}
Before the output embedding, the construction also retains a coordinate $\widehat h_i(c)$ at every row satisfying
\begin{align}
 \sup_{c\in\overline{\mathbb V}^L}\max_{i\in[L]}
 |\widehat h_i(c)-\log q(c)|\le\varepsilon.
 \label{eq:single-tree-message-evidence}
\end{align}
The budgets depend on the topology only through its height. For a fixed topology, the permitted coefficient locations can be fixed independently of the probability tables.

\label{prop:appendix-message-mixture}
Let $1\le h\le L-1$. With $H_R$ and $b_R$ as in Proposition~\ref{prop:appendix-parallel-mixture}, there exists one class
$\Theta=\Theta(D,N,M,D_{\rm ff},B,S;\sqrt3,G_\delta)$ such that
\begin{align}
 \sup_{q\in\mathcal M_{J,R}^h}
 d_{\infty,\mathrm{mask}}(F^{\delta,q},\mathcal F(\Theta))\le\varepsilon,
 \label{eq:height-mixture-uniform-realization}
\end{align}
with
\begin{align}
 N&\le C(h+1)b_R^2,\qquad M\le R,\qquad\log B\le Cb_R^2,\notag\\
 D&\le C\big[L+V+R(J^2+JV)b_R^3\big],\qquad
 D_{\rm ff}\le C\big[LV+R(J^2+JV)b_R^3\big],\notag\\
 S&\le CRL(J^2+JV)b_R^8.
 \label{eq:height-mixture-budgets}
\end{align}
If all component trees share a common rooted topology, one head suffices. The same bounds hold for any further restriction on the component topologies.

\label{thm:shallow-tree-mixture-estimation}
Let $n,L,V\ge 3$, $J,R \ge 1$, and $h\in [L-1]$. 
Use the fixed-cardinality masking schedule $s$ in Section \ref{sec:prelim} for training.
There exists a transformer class $\Theta_h$ of the form \eqref{eq:transformer predictor}, with an architecture depending only on $(n,L,V,J,R,h)$ (specified in Proposition \ref{prop:appendix-message-mixture} with $\delta = \varepsilon = 1/n$), such that for any distribution $p^\star$ on $\mathbb V^L$, the ERM $\widehat{\theta}_h$ over $\Theta_h$ computed from $n$ i.i.d.~samples drawn from $p^\star$ satisfies
\begin{align}
    \mathbb E[\mathcal{L}(\widehat{\theta}_h)] \leq C_{3} \bigg(\frac{s_{\mathsf{max}}}{L} \mathsf{Proj}^h_{J,R}(p^\star) + \frac{K_{\rm sh}}{n}\, \mathsf{poly}\log(n,L,V,J,R) \bigg).  \label{eq:shallow tree estimation error}
\end{align}

Here, $C_{3}>0$ is a universal constant, the expectation is over training samples, and 
\begin{align}\label{eq:Ksh}
    K_{\rm sh} := RL(J^2+JV)h^2.
\end{align}

\label{thm:shallow end-to-end}
Assume the conditions and adopt the notation of Theorem \ref{thm:shallow-tree-mixture-estimation}.

Let $p_{Y\mid S}$ denote the output distribution of the $T$-step MDM sampler using the ERM-based mask predictor $p_{\widehat{\theta}_h}$ and the realized unmasking sets $\mathcal{S}=(S^1,\ldots,S^T)$ with $|S^t| = s_t$.



Then for any $1\leq T \leq L$, one has 
\begin{align}
    & \mathbb E_{\{X^{(i)}\}_{i=1}^n,S} \big[D_{\mathrm{KL}} \big( p^\star \,\|\, p_{Y\mid S}\big)\big] \notag \\
    &\quad \leq C_{4}\bigg( \varepsilon_{\mathsf{parall}}(p^\star;s) + s_{\mathsf{max}} \mathsf{Proj}^h_{J,R}(p^\star) + \frac{L K_{\rm sh}}{n}\, \mathsf{poly}\log (n,L,V,J,R)\bigg), \label{eq:shallow tree sampling error}
\end{align}
where $C_{4}>0$ is a universal constant, and the expectation is over the training samples and random unmasking sets $S$.

\label{lem:nn-logarithm}
For $0<\tau\le1/2$ and $0<\epsilon\le1/2$, there exists $\phi_{\log}\in\mathsf{NN}(W,d,B,S)$ with
\begin{align*}
 W&=O\big(\log^2 \epsilon^{-1}\cdot \log \tau^{-1}\big),&
    d&=O\big(\log^2 \epsilon^{-1} \vee\log \tau^{-1} \big),\\
 B&=O\big(\tau^{-1}\vee\log^2 \tau^{-1}\big),&
 S&=O\big((\log \epsilon^{-1}+\log \tau^{-1} )^8\big),
\end{align*}
such that $\sup_{x\in[\tau,1]}|\phi_{\log}(x)-\log x|\le\epsilon$.

\label{lem:tc-dtc-schedules}
Fix $L\geq2$ and an integer $T$ satisfying $2+2\log(eL)\leq T<L$. 
There exist forward masking schedules $s^{\mathsf{TC}}$ and $s^{\mathsf{DTC}}$, each consisting of $T$ positive integers summing to $L$ and depending only on $(L,T)$, such that, for every target distribution $p^\star$ on $\mathbb V^L$,
\begin{align}
    \varepsilon_{\mathsf{parall}}(p^{\star};s^{\mathsf{TC}})
    \leq\frac{6\log(eL)}{T}\mathsf{TC}(p^\star),
    \quad \varepsilon_{\mathsf{parall}}(p^\star;s^{\mathsf{DTC}})
    \leq\frac{6\log(eL)}{T}\mathsf{DTC}(p^\star).
    \label{eq:tc-dtc-schedule-bounds}
\end{align}
For $T=L$, the singleton schedule has zero parallelization error.

We first write the parallelization error in terms of average mutual information. For $j\in[L]$, define
\[
    Z_j:=\mathbb E_{\substack{|W|=j-1\\i\notin W}}\big[I(X_i;X_W)\big],
    \qquad d_r:=Z_{r+1}-Z_r,\quad r\in[L-1],
\]
where $I(\cdot;\cdot)$ denotes the mutual information, $(W,i)$ is uniform among pairs of the indicated sizes and $X \sim p^\star$. 
For a fixed $i$, coupling nested uniform subsets of $[L]\setminus\{i\}$ gives $I(X_i;X_W)\leq I(X_i;X_{W'})$ whenever $W\subseteq W'$. Averaging over $i$ therefore gives $0=Z_1\leq\cdots\leq Z_L$, so $d_r\geq0$.

Let $H_j$ be the average of $H(X_W)$ over uniform subsets $W\subseteq[L]$ of size $j$, with $H_0=0$. Then by the connection between entropy and mutual information,
\begin{align}
    Z_j = \mathbb E_{\substack{|W|=j-1\\i\notin W}}\big[H(X_i)+ H(X_W) - H(X_{W\cup\{i\}}) \big]  = H_1 + H_{j-1} - H_j. \notag
\end{align}
Moreover, 
\begin{align*}
    \sum_{j=1}^L Z_j=LH_1-H_L=\mathsf{TC}(p^\star), \quad LZ_L=\sum_{i=1}^L I(X_i;X_{[L]\setminus\{i\}})=\mathsf{TC}(p^\star)+\mathsf{DTC}(p^\star). 
\end{align*}
Therefore, 
\begin{align}
    \mathsf{TC}(p^\star)=\sum_{r=1}^{L-1}(L-r)d_r,
    \qquad
    \mathsf{DTC}(p^\star)=\sum_{r=1}^{L-1}r\,d_r.
    \label{eq:tc-dtc-increments}
\end{align}

For the construction below, we list batch sizes in generation order as $s^{\rm rev}=(\tilde{s}_1,\cdots,\tilde{s}_T) := (s_T,\ldots,s_1)$.

Set $N_j:=\sum_{\ell=1}^j \tilde{s}_\ell$ as the total number of elements in the first $j$ unmasking batches, and $N_0=0$. 
Hence, $|W^j| = N_{T-j}$ and $|W^j \cup S^j| = N_{T-j+1}$. 
Consider

\begin{align}
    E_j &:= \mathbb E_S \big[ \mathsf{TC}_{p^\star} (X_{S^j} \mid X_{W^j})\big]\notag \\
    &= \mathbb E_S \big[ \sum_{i\in S^j} H(X_i \mid X_{W^j}) - H(X_{S^j} \mid X_{W^j}) \big] \notag \\
    & = s_j (H_1 - Z_{N_{T-j}+1}) - (H_{N_{T-j+1}} - H_{N_{T-j}}) \notag\\
    & = \sum_{v=N_{T-j}+1}^{N_{T-j+1}}(Z_v - Z_{N_{T-j}+1}) = \sum_{r=N_{T-j}+1}^{N_{T-j+1}-1}(N_{T-j+1}-r)d_r. \label{eq:batch-parallel-cost}
\end{align}
Summing over batches gives
\begin{align}
    \varepsilon_{\mathsf{parall}}(p^\star;s)=\sum_{j=1}^T E_j.   \label{eq:parallel-cost-sum}
\end{align}
